      ctx.save();
      ctx.beginPath();
      ctx.arc(W / 2, H / 2, shockP * 1300, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(255, 51, 0, ${(1 - shockP) * 0.65})`;
      ctx.lineWidth = lerp(60, 2, shockP);
      ctx.stroke();
      ctx.restore();
    }

    // Exit transition at end of Scene 1 (4.65s - 5.0s)
    const exitP = easeInOutCubic(prog(t, 4.65, 0.35));
    const entryP = springProg(t, 2.22, 0.78, 0.72, 11);

    ctx.save();
    const yShift = lerp(40, 0, entryP) - exitP * 60;
    ctx.globalAlpha = clamp(entryP) * (1 - exitP);

    // Official Lumail Lockup (strictly unrotated, exact proportions: height 116px -> width 397.3px)
    const lockH = 118;
    const lockW = (311.71 / 91) * lockH;
    drawLumailLockup(ctx, (W - lockW) / 2, 310 + yShift, lockH, false);

    // Tagline below lockup
    const tagP = easeProg(t, 2.65, 0.6);
    ctx.globalAlpha = tagP * (1 - exitP);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '500 44px "Inter", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText('Write the email. We handle the rest.', W / 2, 515 + yShift);

    ctx.font = '400 24px "Geist", sans-serif';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(
      'Newsletters, automated sequences, and transactional email from one domain.',
      W / 2,
      575 + yShift
    );

    // Three precision pills at bottom
    const pills = [
      '139 MCP TOOLS',
      '3,000 EMAILS/MO FREE',
      'ZERO SUBSCRIBER TAX',
    ];
    const pillStartY = 655 + yShift;
    const spacing = 310;
    pills.forEach((label, i) => {
      const pp = springProg(t, 2.95 + i * 0.14, 0.55, 0.75, 11);
      if (pp <= 0) return;
      ctx.save();
      ctx.globalAlpha = pp * (1 - exitP);
      const px = W / 2 + (i - 1) * spacing;
      const py = pillStartY + (1 - pp) * 24;
      roundRect(ctx, px - 138, py - 24, 276, 48, 24);
      ctx.fillStyle = COLORS.white;
      ctx.fill();
      ctx.strokeStyle = COLORS.border;
      ctx.lineWidth = 1.5;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(px - 108, py, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.flare;
      ctx.fill();

      ctx.font = '500 15px "Geist Mono", monospace';
      ctx.fillStyle = COLORS.ink;
      ctx.textAlign = 'center';
      ctx.fillText(label, px + 8, py + 1);
      ctx.restore();
    });

    ctx.restore();
  }
}

