  // Subheadline
  const subP = easeProg(lt, 1.45, 0.6);
  ctx.save();
  ctx.globalAlpha = subP * (1 - exitP);
  ctx.textAlign = 'center';
  ctx.font = '400 26px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText(
    "You'll actually like sending emails. And you'll make more money. That's the deal.",
