    roundRect(ctx, formX, formY, formW, 76, 16);
    ctx.fillStyle = COLORS.white;
    ctx.fill();
    ctx.strokeStyle = isFocused ? 'rgba(26, 22, 20, 0.35)' : COLORS.border;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Left icon divider
    ctx.beginPath();
    ctx.moveTo(formX + 74, formY);
    ctx.lineTo(formX + 74, formY + 76);
    ctx.strokeStyle = COLORS.border;
    ctx.stroke();

    // Globe icon
    ctx.strokeStyle = COLORS.mutedFg;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(formX + 37, formY + 38, 14, 0, Math.PI * 2);
