    ctx.fillStyle = typeP > 0 ? COLORS.ink : 'rgba(95, 88, 83, 0.6)';
    ctx.fillText(shownText, formX + 96, formY + 39);

    if (lt >= 2.3 && lt < 3.8) {
      const tw = typeP > 0 ? ctx.measureText(shownText).width : 0;
