    // Footnote
    ctx.font = '400 17px "Geist", sans-serif';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.textAlign = 'center';
    ctx.fillText('3,000 emails/month free · no card', W / 2, btnY + 108);
    ctx.restore();
  }

  // Bottom Platform Migration Strip (exact match to lumail.io homepage bar)
  const barP = easeProg(lt, 2.2, 0.7);
  if (barP > 0) {
    ctx.save();
    const barY = 835 + masterY + (1 - barP) * 30;
