      { name: 'beehiiv', bg: '#111111', fg: '#FFFFFF', letter: 'b' },
      { name: 'ActiveCampaign', bg: '#356AE6', fg: '#FFFFFF', letter: 'A' },
      { name: 'MailerLite', bg: '#09C269', fg: '#FFFFFF', letter: 'M' },
