      ctx.fillText(p.letter, px + 15, py + 1);

      ctx.font = '500 18px "Geist", sans-serif';
      ctx.fillStyle = COLORS.ink;
      ctx.textAlign = 'left';
      ctx.fillText(p.name, px + 40, py + 1);
      px += ctx.measureText(p.name).width + 74;
    });
    ctx.restore();
  }

  ctx.restore();
}

