  const exitP = easeInOutCubic(prog(lt, 5.1, 0.4));
  drawTopChrome(ctx, 'MIGRATION · MCP', '02', false, (1 - exitP));

  ctx.save();
  ctx.globalAlpha = 1 - exitP;
  const shiftY = -exitP * 40;

  // Left Column: Editorial Headline + 01, 02, 03 Vertical Timeline
  const leftP = springProg(lt, 0.05, 0.7, 0.75, 11);
  ctx.save();
  ctx.translate(0, (1 - leftP) * 35 + shiftY);
  ctx.globalAlpha = clamp(leftP) * (1 - exitP);

  drawEyebrowPill(ctx, 120, 175, '11 PLATFORMS SUPPORTED');

  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = '500 54px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Migrate from', 120, 268);

  // Cycling provider badge in Peach highlight box (like lumail.io #migrate)
  const providers = [
    { name: '“Mailchimp”', color: '#FFE01B', fg: '#111' },
    { name: '“Kit”', color: '#111111', fg: '#FFF' },
    { name: '“beehiiv”', color: '#111111', fg: '#FFF' },
    { name: '“Brevo”', color: '#0B996E', fg: '#FFF' },
    { name: '“Mailchimp”', color: '#FFE01B', fg: '#111' },
  ];
  const pIdx = Math.min(providers.length - 1, Math.floor(clamp(lt / 2.2, 0, 0.999) * providers.length));
  const curProv = providers[pIdx];

  const mWidth = ctx.measureText('Migrate from ').width;
  const provW = ctx.measureText(curProv.name).width + 28;
  roundRect(ctx, 120 + mWidth, 232, provW, 68, 12);
  ctx.fillStyle = COLORS.peach;
  ctx.fill();
  ctx.fillStyle = COLORS.ink;
  ctx.fillText(curProv.name, 120 + mWidth + 14, 268);

  ctx.fillStyle = COLORS.ink;
  ctx.fillText('in less than 10 minutes.', 120, 342);

  // Numbered steps 01, 02, 03
  const steps = [
    { num: '01', text: 'Add Lumail on Codex or Claude Code', delay: 0.45 },
    { num: '02', text: 'Ask your agent to migrate everything', delay: 0.85 },
    { num: '03', text: 'Be ready in less than 10 minutes', delay: 1.25 },
  ];

  steps.forEach((st, i) => {
    const sp = easeProg(lt, st.delay, 0.55);
    const sy = 450 + i * 102;
    ctx.save();
    ctx.globalAlpha = sp * (1 - exitP);

    // Number pill
    ctx.font = '500 18px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(st.num, 120, sy);

    // Vertical connector line
    if (i < 2) {
      ctx.strokeStyle = COLORS.border;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(132, sy + 22);
      ctx.lineTo(132, sy + 78);
      ctx.stroke();
    }

    ctx.font = '400 24px "Geist", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(st.text, 176, sy);
    ctx.restore();
  });

  // Single Flare CTA Button
  const ctaP = springProg(lt, 1.55, 0.6, 0.74, 11);
  if (ctaP > 0) {
    ctx.save();
    ctx.globalAlpha = ctaP * (1 - exitP);
    roundRect(ctx, 120, 765, 290, 58, 29);
    ctx.fillStyle = COLORS.flare;
    ctx.fill();
    ctx.font = '500 19px "Geist", sans-serif';
    ctx.fillStyle = COLORS.white;
    ctx.textAlign = 'center';
    ctx.fillText('Get the migration prompt', 120 + 145, 795);
    ctx.restore();
  }
  ctx.restore();

  // Right Column: Soft Wash container (#FBEEE7) + White MCP Terminal Card
  const rightP = springProg(lt, 0.2, 0.75, 0.74, 11);
  ctx.save();
  ctx.translate((1 - rightP) * 50, shiftY);
  ctx.globalAlpha = clamp(rightP) * (1 - exitP);

  const { ix, iy, iw, ih } = drawWashCard(ctx, 940, 175, 860, 680, 32, false);

  // Terminal Header
  ctx.beginPath();
  ctx.moveTo(ix, iy + 58);
  ctx.lineTo(ix + iw, iy + 58);
  ctx.strokeStyle = COLORS.border;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ix + 28 + d * 18, iy + 29, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(26, 22, 20, 0.14)';
    ctx.fill();
  }
  ctx.font = '500 16px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('claude-code — lumail-mcp', ix + 92, iy + 29);

  // Prompt Line
  const promptY = iy + 112;
  ctx.font = '400 20px "Geist Mono", monospace';
  ctx.fillStyle = 'rgba(26, 22, 20, 0.35)';
  ctx.fillText('>', ix + 40, promptY);
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('migrate everything from ', ix + 68, promptY);
  const mw = ctx.measureText('migrate everything from ').width;
  ctx.fillStyle = COLORS.ink;
  ctx.font = '600 20px "Geist Mono", monospace';
  ctx.fillText('Mailchimp', ix + 68 + mw, promptY);

  // MCP Tool Calls with animated counters
  const mcpCalls = [
    {
      fn: 'import_subscribers',
      start: 1.5,
      target: 12847,
      suffix: ' contacts',
      sub: 'tags, custom fields, and double opt-in timestamps preserved',
    },
    {
      fn: 'import_tags',
      start: 2.35,
      target: 14,
      suffix: ' tags',
      sub: 'mapped to organization segments automatically',
    },
    {
      fn: 'import_sequences',
      start: 3.15,
      target: 3,
      suffix: ' workflows',
      sub: 'converted to Lumail graph-based workflow drafts',
    },
  ];

  mcpCalls.forEach((call, idx) => {
    const cp = easeProg(lt, call.start, 0.55);
    if (cp <= 0) return;
    const countP = easeOutQuart(prog(lt, call.start + 0.1, 0.75));
    const currentVal = Math.round(call.target * countP).toLocaleString('en-US');
    const rowY = iy + 185 + idx * 120;

    ctx.save();
    ctx.globalAlpha = cp * (1 - exitP);
    ctx.translate(0, (1 - cp) * 16);

    // Emerald dot ⏺
    ctx.beginPath();
    ctx.arc(ix + 48, rowY, 6, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.emeraldDark;
    ctx.fill();

    ctx.font = '500 20px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(`lumail - ${call.fn}`, ix + 68, rowY);
    const fnW = ctx.measureText(`lumail - ${call.fn} `).width;
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText('(MCP)', ix + 68 + fnW, rowY);

    // Tree result line ⎿
    ctx.font = '500 19px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(`⎿  ${currentVal}${call.suffix}`, ix + 72, rowY + 34);

    ctx.font = '400 15px "Geist", sans-serif';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(call.sub, ix + 280, rowY + 34);

    // Progress bar on right
    roundRect(ctx, ix + iw - 150, rowY - 8, 110, 8, 4);
    ctx.fillStyle = COLORS.muted;
    ctx.fill();
    roundRect(ctx, ix + iw - 150, rowY - 8, 110 * countP, 8, 4);
    ctx.fillStyle = COLORS.emeraldDark;
    ctx.fill();

    ctx.restore();
  });

  // Final Done status
  const doneP = springProg(lt, 4.0, 0.55, 0.7, 12);
  if (doneP > 0) {
    const dy = iy + 545;
    ctx.save();
    ctx.globalAlpha = doneP * (1 - exitP);
    roundRect(ctx, ix + 36, dy - 26, iw - 72, 56, 14);
    ctx.fillStyle = '#ECFDF5';
    ctx.fill();
    ctx.strokeStyle = 'rgba(5, 150, 105, 0.25)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

