import {
  W, H, COLORS, clamp, lerp, easeOutCubic, easeOutQuart, easeOutQuint,
  easeInOutCubic, easeInCubic, spring, prog, easeProg, springProg,
  SPARKLE_PATH_STR, ENVELOPE_PATH_STR, CHECK_PATH_STR, ARROW_RIGHT_PATH_STR,
  roundRect, drawLumailMark, drawLumailLockup, drawSvgIcon,
  drawEyebrowPill, drawWashCard, drawPaperBackground, drawTopChrome
} from '/tmp/scenes_helpers.mjs';

// ============================================================================
// SCENE 1 (0.0s - 5.0s): THE TUESDAY NIGHT PROBLEM -> THE FLARE IGNITION
// ============================================================================
export function renderScene1(ctx, t) {
  drawPaperBackground(ctx, t, 0.5, 0.45);

  const collapseT = prog(t, 2.05, 0.45);
  const collapseEase = easeInCubic(collapseT);
  const afterFlash = t >= 2.25;

  // Phase 1A: Legacy bloated dashboard cards & headline (0.0s - 2.35s)
  if (t < 2.45) {
    ctx.save();
    const outScale = lerp(1, 0.08, collapseEase);
    const outAlpha = 1 - easeOutCubic(prog(t, 2.15, 0.25));
    ctx.translate(W / 2, H / 2);
    ctx.scale(outScale, outScale);
    ctx.translate(-W / 2, -H / 2);
    ctx.globalAlpha = outAlpha;

    // Cluttered background modals representing legacy email tools
    const clutterCards = [
      { x: 110, y: 120, w: 430, h: 250, title: 'Legacy Drag & Drop Builder (2019)', sub: 'Nested <table width="600"> broken in Outlook', badge: 'LAYOUT ERROR', delay: 0.1 },
      { x: 1360, y: 110, w: 450, h: 240, title: ' Audience Billing Alert', sub: '48,200 dormant contacts · +$340/mo overage', badge: 'PER-CONTACT TAX', delay: 0.28 },
      { x: 130, y: 710, w: 460, h: 230, title: 'Campaign Wizard — Step 5 of 7', sub: 'Configure 14 tracking toggles before preview', badge: '23:47 PM · TUESDAY', delay: 0.46 },
      { x: 1330, y: 700, w: 460, h: 240, title: 'Separate Transactional Service', sub: 'DNS mismatch · OTP delayed behind broadcast', badge: '2 DOMAINS · 2 BILLS', delay: 0.64 },
    ];

    clutterCards.forEach((c, idx) => {
      const p = springProg(t, c.delay, 0.65, 0.68, 11);
      if (p <= 0) return;
      ctx.save();
      const floatY = Math.sin(t * 2.5 + idx) * 6;
      const cx = c.x + c.w / 2;
      const cy = c.y + c.h / 2 + floatY;
      ctx.translate(cx, cy);
      ctx.scale(lerp(0.82, 1, p), lerp(0.82, 1, p));
      ctx.translate(-cx, -cy);
      ctx.globalAlpha = outAlpha * clamp(p * 1.2) * 0.88;

      roundRect(ctx, c.x, c.y + floatY, c.w, c.h, 18);
      ctx.fillStyle = COLORS.white;
      ctx.fill();
      ctx.strokeStyle = COLORS.border;
      ctx.lineWidth = 1.5;
      ctx.stroke();

      // Header bar
      roundRect(ctx, c.x, c.y + floatY, c.w, 46, [18, 18, 0, 0]);
      ctx.fillStyle = COLORS.muted;
      ctx.fill();

      // Dots
      for (let d = 0; d < 3; d++) {
        ctx.beginPath();
        ctx.arc(c.x + 22 + d * 16, c.y + floatY + 23, 5, 0, Math.PI * 2);
        ctx.fillStyle = d === 0 ? COLORS.coral : '#D5CFC7';
        ctx.fill();
      }

      // Badge
      ctx.font = '600 11px "Geist Mono", monospace';
      const bw = ctx.measureText(c.badge).width + 18;
      roundRect(ctx, c.x + c.w - bw - 16, c.y + floatY + 11, bw, 24, 6);
      ctx.fillStyle = COLORS.peach;
      ctx.fill();
      ctx.fillStyle = COLORS.ember;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(c.badge, c.x + c.w - bw / 2 - 16, c.y + floatY + 23);

      // Card Content
      ctx.textAlign = 'left';
      ctx.font = '600 18px "Geist", sans-serif';
      ctx.fillStyle = COLORS.ink;
      ctx.fillText(c.title, c.x + 24, c.y + floatY + 84);

      ctx.font = '400 15px "Geist", sans-serif';
      ctx.fillStyle = COLORS.mutedFg;
      ctx.fillText(c.sub, c.x + 24, c.y + floatY + 116);

      // Skeleton UI bars
      roundRect(ctx, c.x + 24, c.y + floatY + 148, c.w - 48, 14, 7);
      ctx.fillStyle = COLORS.muted;
      ctx.fill();
      roundRect(ctx, c.x + 24, c.y + floatY + 174, (c.w - 48) * 0.68, 14, 7);
      ctx.fillStyle = COLORS.peach;
      ctx.fill();

      ctx.restore();
    });

    // Center editorial card
    const mainP = springProg(t, 0.05, 0.7, 0.72, 10);
    ctx.save();
    ctx.translate(W / 2, H / 2);
    ctx.scale(lerp(0.9, 1, mainP), lerp(0.9, 1, mainP));
    ctx.translate(-W / 2, -H / 2);

    roundRect(ctx, 410, 250, 1100, 560, 32);
    ctx.fillStyle = 'rgba(248, 247, 244, 0.94)';
    ctx.fill();
    ctx.strokeStyle = COLORS.border;
    ctx.lineWidth = 2;
    ctx.stroke();

    // Eyebrow pill centered
    const ew = drawEyebrowPill(ctx, W / 2 - 95, 305, 'TUESDAY · 23:48');

    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '500 58px "Inter", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText('Running email marketing', W / 2, 420);
    ctx.fillStyle = COLORS.ember;
    ctx.fillText("shouldn't feel like a second job.", W / 2, 492);

    const subP = easeProg(t, 0.65, 0.6);
    ctx.globalAlpha = outAlpha * subP;
    ctx.font = '400 24px "Geist", sans-serif';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(
      "You didn't start a business to fight templates, pick settings,",
      W / 2,
      588
    );
    ctx.fillText(
      'and spend Tuesday night on a campaign that still looks like 2019.',
      W / 2,
      624
    );

    // Strikethrough line sweeping across at 1.65s
    const strikeP = easeOutQuart(prog(t, 1.6, 0.45));
    if (strikeP > 0) {
      ctx.strokeStyle = COLORS.flare;
      ctx.lineWidth = 5;
      ctx.beginPath();
      ctx.moveTo(490, 492);
      ctx.lineTo(490 + 940 * strikeP, 492);
      ctx.stroke();
    }
    ctx.restore();
    ctx.restore();
  }

  // Phase 1B: The Flare Ignition Shockwave (2.2s - 5.0s)
  if (t >= 2.15) {
    const shockP = easeOutQuart(prog(t, 2.15, 0.85));
    if (shockP < 1) {
      ctx.save();
      ctx.beginPath();
      ctx.arc(W / 2, H / 2, shockP * 1300, 0, Math.PI * 2);
      ctx.strokeStyle = `rgba(255, 51, 0, ${(1 - shockP) * 0.65})`;
      ctx.lineWidth = lerp(60, 2, shockP);
      ctx.stroke();
      ctx.restore();
    }

    // Exit transition at end of Scene 1 (4.65s - 5.0s)
    const exitP = easeInOutCubic(prog(t, 4.65, 0.35));
    const entryP = springProg(t, 2.22, 0.78, 0.72, 11);

    ctx.save();
    const yShift = lerp(40, 0, entryP) - exitP * 60;
    ctx.globalAlpha = clamp(entryP) * (1 - exitP);

    // Official Lumail Lockup (strictly unrotated, exact proportions: height 116px -> width 397.3px)
    const lockH = 118;
    const lockW = (311.71 / 91) * lockH;
    drawLumailLockup(ctx, (W - lockW) / 2, 310 + yShift, lockH, false);

    // Tagline below lockup
    const tagP = easeProg(t, 2.65, 0.6);
    ctx.globalAlpha = tagP * (1 - exitP);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.font = '500 44px "Inter", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText('Write the email. We handle the rest.', W / 2, 515 + yShift);

    ctx.font = '400 24px "Geist", sans-serif';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(
      'Newsletters, automated sequences, and transactional email from one domain.',
      W / 2,
      575 + yShift
    );

    // Three precision pills at bottom
    const pills = [
      '139 MCP TOOLS',
      '3,000 EMAILS/MO FREE',
      'ZERO SUBSCRIBER TAX',
    ];
    const pillStartY = 655 + yShift;
    const spacing = 310;
    pills.forEach((label, i) => {
      const pp = springProg(t, 2.95 + i * 0.14, 0.55, 0.75, 11);
      if (pp <= 0) return;
      ctx.save();
      ctx.globalAlpha = pp * (1 - exitP);
      const px = W / 2 + (i - 1) * spacing;
      const py = pillStartY + (1 - pp) * 24;
      roundRect(ctx, px - 138, py - 24, 276, 48, 24);
      ctx.fillStyle = COLORS.white;
      ctx.fill();
      ctx.strokeStyle = COLORS.border;
      ctx.lineWidth = 1.5;
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(px - 108, py, 4.5, 0, Math.PI * 2);
      ctx.fillStyle = COLORS.flare;
      ctx.fill();

      ctx.font = '500 15px "Geist Mono", monospace';
      ctx.fillStyle = COLORS.ink;
      ctx.textAlign = 'center';
      ctx.fillText(label, px + 8, py + 1);
      ctx.restore();
    });

    ctx.restore();
  }
}

// ============================================================================
// SCENE 2 (5.0s - 10.5s): THE HERO STATEMENT & INTERACTIVE SIGNUP
// ============================================================================
export function renderScene2(ctx, t) {
  const lt = t - 5.0; // 0.0 -> 5.5s
  drawPaperBackground(ctx, t, 0.5, 0.18);
  const exitP = easeInOutCubic(prog(lt, 5.1, 0.4));
  drawTopChrome(ctx, 'LUMAIL.IO', '01', false, easeProg(lt, 0.1, 0.4) * (1 - exitP));

  ctx.save();
  ctx.globalAlpha = 1 - exitP;
  const masterY = -exitP * 50;

  // Hand-drawn Caveat annotation in top-right (signature from lumail.io homepage)
  const handP = easeProg(lt, 0.5, 0.6);
  if (handP > 0) {
    ctx.save();
    ctx.globalAlpha = handP * (1 - exitP);
    ctx.font = '600 32px "Caveat", cursive';
    ctx.fillStyle = COLORS.ink;
    ctx.textAlign = 'left';
    ctx.fillText('Lumail in under a minute', 1355, 165 + masterY);
    // Curved arrow pointing toward headline/form
    ctx.strokeStyle = 'rgba(26, 22, 20, 0.55)';
    ctx.lineWidth = 2.5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(1340, 168 + masterY);
    ctx.quadraticCurveTo(1290, 180 + masterY, 1265, 215 + masterY);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(1262, 198 + masterY);
    ctx.lineTo(1265, 215 + masterY);
    ctx.lineTo(1282, 211 + masterY);
    ctx.stroke();
    ctx.restore();
  }

  // Hero Headline Line 1: "The [✨ AI Tool] that will"
  const h1P = springProg(lt, 0.1, 0.65, 0.74, 11);
  const pill1P = springProg(lt, 0.55, 0.65, 0.62, 12);
  const pill2P = springProg(lt, 1.15, 0.65, 0.62, 12);

  const line1Y = 235 + masterY + (1 - h1P) * 35;
  ctx.save();
  ctx.globalAlpha = clamp(h1P) * (1 - exitP);
  ctx.textBaseline = 'middle';
  ctx.textAlign = 'left';

  // Measure and lay out Line 1 centered around W/2
  // "The " + [✨ AI Tool] + " that will"
  ctx.font = '500 76px "Inter", sans-serif';
  const wThe = ctx.measureText('The ').width;
  const wPill1 = 308;
  const wThatWill = ctx.measureText(' that will').width;
  const totalL1 = wThe + wPill1 + wThatWill;
  let curX = (W - totalL1) / 2;

  ctx.fillStyle = COLORS.ink;
  ctx.fillText('The ', curX, line1Y);
  curX += wThe;

  // Keycap Pill 1: [✨ AI Tool]
  ctx.save();
  const p1cx = curX + wPill1 / 2;
  const p1cy = line1Y - 4;
  ctx.translate(p1cx, p1cy);
  ctx.scale(lerp(0.6, 1, pill1P), lerp(0.6, 1, pill1P));
  ctx.translate(-p1cx, -p1cy);

  ctx.shadowColor = 'rgba(26, 22, 20, 0.14)';
  ctx.shadowBlur = 24;
  ctx.shadowOffsetY = 8;
  roundRect(ctx, curX, line1Y - 50, wPill1, 92, 22);
  ctx.fillStyle = COLORS.white;
  ctx.fill();
  ctx.shadowColor = 'transparent';
  ctx.strokeStyle = COLORS.border;
  ctx.lineWidth = 2;
  ctx.stroke();

  drawSvgIcon(ctx, SPARKLE_PATH_STR, curX + 24, line1Y - 30, 52, COLORS.flare);
  ctx.font = '500 70px "Inter", sans-serif';
  ctx.fillStyle = COLORS.flare;
  ctx.fillText('AI Tool', curX + 86, line1Y + 2);
  ctx.restore();

  curX += wPill1;
  ctx.font = '500 76px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText(' that will', curX, line1Y);

  // Hero Headline Line 2: "make you love [✉️ e-mail] marketing"
  const line2Y = 348 + masterY + (1 - h1P) * 35;
  const wMake = ctx.measureText('make you love ').width;
  const wPill2 = 294;
  const wMkt = ctx.measureText(' marketing').width;
  const totalL2 = wMake + wPill2 + wMkt;
  let curX2 = (W - totalL2) / 2;

  ctx.fillStyle = COLORS.ink;
  ctx.fillText('make you love ', curX2, line2Y);
  curX2 += wMake;

  // Keycap Pill 2: [✉️ e-mail]
  ctx.save();
  const p2cx = curX2 + wPill2 / 2;
  const p2cy = line2Y - 4;
  ctx.translate(p2cx, p2cy);
  ctx.scale(lerp(0.6, 1, pill2P), lerp(0.6, 1, pill2P));
  ctx.translate(-p2cx, -p2cy);

  ctx.shadowColor = 'rgba(26, 22, 20, 0.14)';
  ctx.shadowBlur = 24;
  ctx.shadowOffsetY = 8;
  roundRect(ctx, curX2, line2Y - 50, wPill2, 92, 22);
  ctx.fillStyle = COLORS.white;
  ctx.fill();
  ctx.shadowColor = 'transparent';
  ctx.strokeStyle = COLORS.border;
  ctx.lineWidth = 2;
  ctx.stroke();

  drawSvgIcon(ctx, ENVELOPE_PATH_STR, curX2 + 24, line2Y - 28, 48, COLORS.flare);
  ctx.font = '500 70px "Inter", sans-serif';
  ctx.fillStyle = COLORS.flare;
  ctx.fillText('e-mail', curX2 + 84, line2Y + 2);
  ctx.restore();

  curX2 += wPill2;
  ctx.font = '500 76px "Inter", sans-serif';
  ctx.fillStyle = COLORS.flare;
  ctx.fillText(' marketing', curX2, line2Y);
  ctx.restore();

  // Subheadline
  const subP = easeProg(lt, 1.45, 0.6);
  ctx.save();
  ctx.globalAlpha = subP * (1 - exitP);
  ctx.textAlign = 'center';
  ctx.font = '400 26px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText(
    "You'll actually like sending emails. And you'll make more money. That's the deal.",
    W / 2,
    442 + masterY
  );
  ctx.restore();

  // Interactive Domain Input + Flare CTA Card
  const formP = springProg(lt, 1.75, 0.7, 0.74, 11);
  if (formP > 0) {
    ctx.save();
    const formW = 680;
    const formX = (W - formW) / 2;
    const formY = 500 + masterY + (1 - formP) * 40;
    ctx.globalAlpha = clamp(formP) * (1 - exitP);

    // Input box
    const isFocused = lt >= 2.3;
    if (isFocused) {
      roundRect(ctx, formX - 4, formY - 4, formW + 8, 76 + 8, 20);
      ctx.fillStyle = 'rgba(255, 51, 0, 0.14)';
      ctx.fill();
    }

    roundRect(ctx, formX, formY, formW, 76, 16);
    ctx.fillStyle = COLORS.white;
    ctx.fill();
