    ctx.strokeStyle = COLORS.mutedFg;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(formX + 37, formY + 38, 14, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.ellipse(formX + 37, formY + 38, 6, 14, 0, 0, Math.PI * 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(formX + 23, formY + 38);
    ctx.lineTo(formX + 51, formY + 38);
