    if (lt >= 2.3 && lt < 3.8) {
      const tw = typeP > 0 ? ctx.measureText(shownText).width : 0;
      if (Math.floor(lt * 4) % 2 === 0) {
        ctx.fillStyle = COLORS.flare;
        ctx.fillRect(formX + 98 + tw, formY + 23, 2.5, 30);
