      ctx.textAlign = 'center';
      ctx.fillText('✓ DKIM + SPF READY', formX + formW - 107, formY + 39);
      ctx.restore();
    }

    // Start free Flare CTA button (The one filled Flare action in this view)
    const btnY = formY + 92;
    const clickScale = lt >= 3.85 && lt <= 4.15 ? 0.97 : 1.0;
    ctx.save();
    ctx.translate(W / 2, btnY + 38);
    ctx.scale(clickScale, clickScale);
    ctx.translate(-W / 2, -(btnY + 38));

    ctx.shadowColor = 'rgba(255, 51, 0, 0.28)';
