  ctx.fillText('Read the launch post →', bodyX + 137, ctaBtnY + 30);

  // Bottom Editor Status Bar
  const statusY = iy + ih - 70;
  ctx.strokeStyle = COLORS.border;
  ctx.beginPath();
  ctx.moveTo(ix, statusY);
  ctx.lineTo(ix + iw, statusY);
  ctx.stroke();

  ctx.textAlign = 'left';
  ctx.font = '400 15px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('Inbox preview: 99.8% deliverability · SPF/DKIM aligned', ix + 36, statusY + 35);

  if (lt >= 4.1) {
    const sp = springProg(lt, 4.1, 0.5, 0.72, 12);
    ctx.save();
    ctx.globalAlpha = sp * (1 - exitP);
    roundRect(ctx, ix + iw - 235, statusY + 14, 200, 42, 21);
    ctx.fillStyle = '#ECFDF5';
    ctx.fill();
    ctx.font = '600 14px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.emeraldDark;
    ctx.textAlign = 'center';
    ctx.fillText('● ONE-CLICK READY', ix + iw - 135, statusY + 36);
    ctx.restore();
  }

  ctx.restore();
  ctx.restore();
}

