  const families = ['Inter', 'Geist', 'Geist Mono', 'Caveat'];
  for (const f of families) {
    for (const w of weights) {
      c.font = `${w} 24px "${f}"`;
      c.fillText('Warmup 0123456789', 0, 0);
    }
  }
});

if (mode === 'preview') {
  fs.mkdirSync('/tmp/preview_frames', { recursive: true });
  const sampleTimes = [1.2, 3.4, 7.2, 14.3, 17.5, 20.8, 25.5, 32.8, 38.2, 43.0];
  for (let i = 0; i < sampleTimes.length; i++) {
    const t = sampleTimes[i];
    await page.evaluate((time) => window.renderAtTime(time), t);
    await page.screenshot({ path: `/tmp/preview_frames/sample_${i}_${t}s.png`, type: 'png' });
  }
  console.log('Saved 10 preview frames to /tmp/preview_frames/');
} else if (mode === 'full') {
  const FPS = 60;
  const DURATION = 45;
  const TOTAL_FRAMES = FPS * DURATION; // 2700 frames
  const outPath = '/private/var/folders/7z/5mtgxwxx4zs9ppgzm942gbmh0000gn/T/workspace.6AMES2/app/video.mp4';

  const ff = spawn('ffmpeg', [
    '-y',
    '-f', 'image2pipe',
    '-vcodec', 'mjpeg',
    '-framerate', String(FPS),
    '-i', '-',
    '-i', '/tmp/lumail_audio.wav',
    '-map', '0:v:0',
    '-map', '1:a:0',
    '-c:v', 'libx264',
    '-preset', 'medium',
    '-crf', '16',
    '-pix_fmt', 'yuv420p',
    '-r', String(FPS),
    '-c:a', 'aac',
    '-b:a', '192k',
    '-ar', '48000',
    '-shortest',
    '-movflags', '+faststart',
    outPath,
  ], { stdio: ['pipe', 'inherit', 'inherit'] });

  const startTime = Date.now();
  for (let f = 0; f < TOTAL_FRAMES; f++) {
    const t = f / FPS;
    const b64 = await page.evaluate((time) => {
      window.renderAtTime(time);
      return document.getElementById('c').toDataURL('image/jpeg', 0.96).slice(23);
    }, t);
    const buf = Buffer.from(b64, 'base64');
    if (!ff.stdin.write(buf)) {
      await new Promise((resolve) => ff.stdin.once('drain', resolve));
    }
    if ((f + 1) % 300 === 0 || f === TOTAL_FRAMES - 1) {
      const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
      console.log(`Rendered frame ${f + 1}/${TOTAL_FRAMES} (${((f + 1) / TOTAL_FRAMES * 100).toFixed(0)}%) in ${elapsed}s`);
    }
  }

  ff.stdin.end();
  await new Promise((resolve, reject) => {
    ff.on('close', (code) => (code === 0 ? resolve() : reject(new Error(`ffmpeg exited ${code}`))));
  });
  console.log('Successfully rendered video.mp4!');
}

await browser.close();

