import {
  W, H, COLORS, clamp, lerp, easeOutCubic, easeOutQuart, easeOutQuint,
  easeInOutCubic, spring, prog, easeProg, springProg,
  SPARKLE_PATH_STR, ENVELOPE_PATH_STR, CHECK_PATH_STR, ARROW_RIGHT_PATH_STR,
  roundRect, drawLumailMark, drawLumailLockup, drawSvgIcon,
  drawEyebrowPill, drawWashCard, drawPaperBackground, drawTopChrome
} from '/tmp/scenes_helpers.mjs';

// ============================================================================
// SCENE 5 (22.0s - 28.5s): YOUR AI CAN SEND THE CAMPAIGN — 139 MCP TOOLS (DARK VOID)
// ============================================================================
export function renderScene5(ctx, t) {
  const lt = t - 22.0; // 0.0 -> 6.5s
  const exitP = easeInOutCubic(prog(lt, 6.05, 0.45));

  // Void Dark Canvas (#08090A) with subtle Flare/Ember ambient glow
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(0, 0, W, H);

  const grad = ctx.createRadialGradient(W * 0.35, H * 0.5, 40, W * 0.35, H * 0.5, 920);
  grad.addColorStop(0, 'rgba(255, 51, 0, 0.14)');
  grad.addColorStop(0.55, 'rgba(196, 50, 10, 0.05)');
  grad.addColorStop(1, 'rgba(8, 9, 10, 0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Subtle dark grid
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  ctx.lineWidth = 1;
  const grid = 80;
  const offset = (t * 16) % grid;
  ctx.beginPath();
  for (let x = offset; x < W; x += grid) {
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H);
  }
  for (let y = 0; y < H; y += grid) {
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
  }
  ctx.stroke();

  drawTopChrome(ctx, 'AGENT ACCESS · 139 MCP TOOLS', '04', true, 1 - exitP);

  ctx.save();
  ctx.globalAlpha = 1 - exitP;
  const shiftY = -exitP * 45;

  // Left Column: Claude MCP Terminal Window (exact match to lumail.io #agents)
  const termP = springProg(lt, 0.08, 0.72, 0.74, 11);
  ctx.save();
  ctx.translate((1 - termP) * -50, shiftY);
  ctx.globalAlpha = clamp(termP) * (1 - exitP);

  const { ix, iy, iw, ih } = drawWashCard(ctx, 100, 160, 1000, 720, 26, true);

  // Terminal Header Bar
  ctx.strokeStyle = COLORS.darkBorder;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(ix, iy + 62);
  ctx.lineTo(ix + iw, iy + 62);
  ctx.stroke();

  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ix + 28 + d * 18, iy + 31, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.16)';
    ctx.fill();
  }

  ctx.font = '500 16px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.darkMutedFg;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('claude', ix + 92, iy + 31);

  // Right badge: [● lumail · 139 tools]
  const badgeW = 212;
  roundRect(ctx, ix + iw - badgeW - 24, iy + 14, badgeW, 34, 8);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.04)';
  ctx.fill();
  ctx.strokeStyle = COLORS.darkBorder;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(ix + iw - badgeW - 6, iy + 31, 4.5, 0, Math.PI * 2);
  ctx.fillStyle = COLORS.emerald;
  ctx.fill();

  ctx.font = '500 14px "Geist Mono", monospace';
  ctx.fillStyle = '#F7F8F8';
  ctx.fillText('lumail · 139 tools', ix + iw - badgeW + 8, iy + 31);

  // User Query 1
  const q1Y = iy + 114;
  ctx.font = '400 19px "Geist Mono", monospace';
  ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
  ctx.fillText('>', ix + 36, q1Y);
  ctx.fillStyle = '#D1D5DB';
  ctx.fillText('who clicked the pricing link but never bought?', ix + 64, q1Y);

  // 3 Live MCP Tool Executions
  const agentSteps = [
    {
      fn: 'lumail - query_subscribers',
      arg: '(clicked: "/pricing")',
      res: '312 subscribers',
      start: 0.95,
    },
    {
      fn: 'lumail - bulk_add_tags',
      arg: '(tags: ["hot-lead"])',
      res: '312 tagged',
      start: 1.95,
    },
    {
      fn: 'lumail - add_subscriber_to_workflow',
      arg: '(workflow: "Objections")',
      res: '312 enrolled',
      start: 2.95,
    },
  ];

  agentSteps.forEach((st, idx) => {
    const sp = easeProg(lt, st.start, 0.55);
    if (sp <= 0) return;
    const sy = iy + 182 + idx * 108;

    ctx.save();
    ctx.globalAlpha = sp * (1 - exitP);
    ctx.translate(0, (1 - sp) * 16);

    ctx.beginPath();
    ctx.arc(ix + 44, sy, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.emerald;
    ctx.fill();

    ctx.font = '500 18px "Geist Mono", monospace';
    ctx.fillStyle = '#F7F8F8';
    ctx.fillText(st.fn, ix + 64, sy);
    const w1 = ctx.measureText(st.fn + ' ').width;

    ctx.fillStyle = COLORS.darkMutedFg;
    ctx.fillText('(MCP) ', ix + 64 + w1, sy);
    const w2 = ctx.measureText('(MCP) ').width;

    ctx.fillStyle = COLORS.coral;
    ctx.fillText(st.arg, ix + 64 + w1 + w2, sy);

    // Output line
    ctx.font = '400 18px "Geist Mono", monospace';
    ctx.fillStyle = '#A1A1AA';
    ctx.fillText(`⎿  ${st.res}`, ix + 68, sy + 34);
    ctx.restore();
  });

  // Done confirmation line
  const doneP = easeProg(lt, 3.85, 0.5);
  if (doneP > 0) {
    const dy = iy + 512;
    ctx.save();
    ctx.globalAlpha = doneP * (1 - exitP);
    ctx.beginPath();
    ctx.arc(ix + 44, dy, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.emerald;
    ctx.fill();

    ctx.font = '500 19px "Geist Mono", monospace';
    ctx.fillStyle = '#F7F8F8';
    ctx.fillText('Done. The first email goes out in 2 hours.', ix + 64, dy);
    ctx.restore();
  }

  // Follow-up input box at bottom of terminal: "> show me the numbers on Thursday"
  const nextP = easeProg(lt, 4.35, 0.55);
  if (nextP > 0) {
    const bx = ix + 34;
    const by = iy + 562;
    const bw = iw - 68;
    ctx.save();
    ctx.globalAlpha = nextP * (1 - exitP);
    roundRect(ctx, bx, by, bw, 62, 14);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.fill();
    ctx.strokeStyle = COLORS.darkBorder;
    ctx.stroke();

    const promptStr = 'show me the numbers on Thursday';
    const typeP = prog(lt, 4.5, 0.95);
    const shown = promptStr.slice(0, Math.floor(typeP * promptStr.length));

    ctx.font = '400 18px "Geist Mono", monospace';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
    ctx.fillText('>', bx + 22, by + 31);
    ctx.fillStyle = '#F7F8F8';
    ctx.fillText(shown, bx + 48, by + 31);

    const curW = ctx.measureText(shown).width;
    if (Math.floor(lt * 4) % 2 === 0) {
      ctx.fillStyle = COLORS.flare;
      ctx.fillRect(bx + 52 + curW, by + 18, 9, 24);
    }
    ctx.restore();
  }
  ctx.restore();

  // Right Column: Headline, Copy, and Agent Ecosystem Grid
  const rightP = springProg(lt, 0.25, 0.75, 0.74, 11);
  ctx.save();
  ctx.translate((1 - rightP) * 45, shiftY);
  ctx.globalAlpha = clamp(rightP) * (1 - exitP);

  drawEyebrowPill(ctx, 1160, 175, 'AI · MODEL CONTEXT PROTOCOL', true);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = '500 56px "Inter", sans-serif';
  ctx.fillStyle = '#F7F8F8';
  ctx.fillText('Your AI can send', 1160, 270);
  ctx.fillStyle = COLORS.flare;
  ctx.fillText('the campaign.', 1160, 340);

  ctx.font = '400 22px "Geist", sans-serif';
  ctx.fillStyle = COLORS.darkMutedFg;
  ctx.fillText('Connect the agent you already use. It drafts,', 1160, 418);
  ctx.fillText('segments, and schedules. You keep the last click.', 1160, 452);
  ctx.fillText('No dashboard tour required.', 1160, 486);

  // Connected Agent Cards Grid (Claude Code, Codex, ChatGPT, Lumail CLI)
  const agents = [
    { name: 'Claude Code', sub: 'lumail.io/claude-code/install', tag: 'PLUGIN + MCP' },
    { name: 'OpenAI Codex', sub: 'lumail.io/codex/install', tag: 'OAUTH 2.1' },
    { name: 'ChatGPT', sub: 'https://lumail.io/mcp', tag: 'SCOPED OAUTH' },
    { name: 'Lumail CLI + SDK', sub: 'lumail campaigns send', tag: 'TERMINAL + TS' },
  ];

  agents.forEach((ag, i) => {
    const ap = springProg(lt, 0.8 + i * 0.22, 0.6, 0.74, 11);
    if (ap <= 0) return;
    const ay = 540 + i * 82;
    ctx.save();
    ctx.globalAlpha = ap * (1 - exitP);
    roundRect(ctx, 1160, ay, 660, 68, 16);
    ctx.fillStyle = COLORS.darkCard;
    ctx.fill();
    ctx.strokeStyle = COLORS.darkBorder;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Dark Lumail mark on left or status dot
    ctx.beginPath();
    ctx.arc(1192, ay + 34, 5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.flare;
    ctx.fill();

    ctx.font = '600 19px "Geist", sans-serif';
    ctx.fillStyle = '#F7F8F8';
    ctx.textAlign = 'left';
    ctx.fillText(ag.name, 1214, ay + 25);

    ctx.font = '400 14px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.darkMutedFg;
    ctx.fillText(ag.sub, 1214, ay + 47);

    // Right Tag
    ctx.font = '500 12px "Geist Mono", monospace';
    const tw = ctx.measureText(ag.tag).width + 24;
    roundRect(ctx, 1160 + 660 - tw - 20, ay + 19, tw, 30, 8);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.06)';
    ctx.fill();
    ctx.fillStyle = '#E5E7EB';
    ctx.textAlign = 'center';
    ctx.fillText(ag.tag, 1160 + 660 - tw / 2 - 20, ay + 35);

    ctx.restore();
  });

  ctx.restore();
  ctx.restore();
}

// ============================================================================
// SCENE 6 (28.5s - 34.5s): WORKFLOWS THAT KEEP RUNNING + TRANSACTIONAL PRIORITY LANE
// ============================================================================
export function renderScene6(ctx, t) {
  const lt = t - 28.5; // 0.0 -> 6.0s
  drawPaperBackground(ctx, t, 0.5, 0.5);
  const exitP = easeInOutCubic(prog(lt, 5.55, 0.45));
  drawTopChrome(ctx, 'WORKFLOWS & TRANSACTIONAL', '05', false, 1 - exitP);

  ctx.save();
  ctx.globalAlpha = 1 - exitP;
  const shiftY = -exitP * 40;

  // Left Half: Visual Workflow Graph ("Welcome sequence" from lumail.io)
  const leftP = springProg(lt, 0.05, 0.7, 0.74, 11);
  ctx.save();
  ctx.translate((1 - leftP) * -40, shiftY);
  ctx.globalAlpha = clamp(leftP) * (1 - exitP);

  drawEyebrowPill(ctx, 96, 125, 'Workflows');
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = '500 42px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Sequences that keep running.', 96, 200);
  ctx.font = '400 19px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('Welcome, launch, follow-up. Publish once. Lumail handles enrolment & exits.', 96, 244);

  const wf = drawWashCard(ctx, 96, 280, 830, 690, 24, false);

  // Window header
  ctx.strokeStyle = COLORS.border;
  ctx.beginPath();
  ctx.moveTo(wf.ix, wf.iy + 52);
  ctx.lineTo(wf.ix + wf.iw, wf.iy + 52);
  ctx.stroke();
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(wf.ix + 24 + d * 16, wf.iy + 26, 5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(26, 22, 20, 0.14)';
    ctx.fill();
  }
  ctx.font = '500 15px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('Welcome sequence · Published v3', wf.ix + 82, wf.iy + 26);

  // Graph Nodes
  const cx = wf.ix + wf.iw / 2;
  const nodes = [
    { y: wf.iy + 104, label: 'Tag added', val: 'newsletter', tag: 'TRIGGER', delay: 0.35 },
    { y: wf.iy + 224, label: 'Send email', val: 'Welcome, start here', tag: 'ACTION', delay: 0.85 },
    { y: wf.iy + 344, label: 'Wait', val: '2 days', tag: 'DELAY', delay: 1.35 },
    { y: wf.iy + 464, label: 'If opened', val: 'the welcome email', tag: 'CONDITION', delay: 1.85 },
  ];

  // Draw connecting edges + animated pulse dots
  nodes.forEach((n, idx) => {
    const np = springProg(lt, n.delay, 0.55, 0.72, 12);
    if (np <= 0) return;

    if (idx > 0) {
      const prevY = nodes[idx - 1].y + 36;
      const curY = n.y - 36;
      ctx.strokeStyle = COLORS.border;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(cx, prevY);
      ctx.lineTo(cx, curY);
      ctx.stroke();

      // Animated data pulse along edge
      const pulseU = (lt * 1.4 - idx * 0.3) % 1;
      if (pulseU > 0 && pulseU < 1) {
        ctx.beginPath();
        ctx.arc(cx, lerp(prevY, curY, pulseU), 4.5, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.flare;
        ctx.fill();
      }
    }

    ctx.save();
    ctx.translate(cx, n.y);
    ctx.scale(lerp(0.85, 1, np), lerp(0.85, 1, np));
    ctx.translate(-cx, -n.y);
    ctx.globalAlpha = np * (1 - exitP);

    const nw = 440;
    const nh = 72;
    roundRect(ctx, cx - nw / 2, n.y - nh / 2, nw, nh, 14);
    ctx.fillStyle = COLORS.white;
    ctx.fill();
    ctx.strokeStyle = idx === 3 ? COLORS.coral : COLORS.border;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Left icon square
    roundRect(ctx, cx - nw / 2 + 16, n.y - 22, 44, 44, 10);
    ctx.fillStyle = COLORS.peach;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(cx - nw / 2 + 38, n.y, 5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.ember;
    ctx.fill();

    ctx.textAlign = 'left';
    ctx.font = '500 18px "Geist", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(n.label, cx - nw / 2 + 76, n.y - 10);

    ctx.font = '400 15px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(n.val, cx - nw / 2 + 76, n.y + 14);

    // Right badge
    ctx.font = '500 11px "Geist Mono", monospace';
    const tw = ctx.measureText(n.tag).width + 18;
    roundRect(ctx, cx + nw / 2 - tw - 16, n.y - 12, tw, 24, 6);
    ctx.fillStyle = COLORS.muted;
    ctx.fill();
    ctx.fillStyle = COLORS.mutedFg;
    ctx.textAlign = 'center';
    ctx.fillText(n.tag, cx + nw / 2 - tw / 2 - 16, n.y + 1);
    ctx.restore();
  });

  // Branching Yes / No outcomes below "If opened"
  const branchP = springProg(lt, 2.35, 0.55, 0.72, 12);
  if (branchP > 0) {
    ctx.save();
    ctx.globalAlpha = branchP * (1 - exitP);
    const startY = nodes[3].y + 36;
    const branchY = wf.iy + 585;

    ctx.strokeStyle = COLORS.border;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx, startY);
    ctx.lineTo(cx - 145, branchY - 28);
    ctx.moveTo(cx, startY);
    ctx.lineTo(cx + 145, branchY - 28);
    ctx.stroke();

    // Yes node
    roundRect(ctx, cx - 265, branchY - 28, 230, 56, 12);
    ctx.fillStyle = '#ECFDF5';
    ctx.fill();
    ctx.strokeStyle = 'rgba(5, 150, 105, 0.3)';
    ctx.stroke();
    ctx.font = '600 15px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.emeraldDark;
    ctx.textAlign = 'center';
    ctx.fillText('YES · Send pitch offer', cx - 150, branchY + 1);

    // No node
    roundRect(ctx, cx + 35, branchY - 28, 230, 56, 12);
    ctx.fillStyle = COLORS.muted;
    ctx.fill();
    ctx.strokeStyle = COLORS.border;
    ctx.stroke();
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText('NO · Re-send with new subject', cx + 150, branchY + 1);
    ctx.restore();
  }
  ctx.restore();

  // Right Half: Transactional Email — "Replace Resend. Same domain." + Priority Lane
  const rightP = springProg(lt, 0.25, 0.75, 0.74, 11);
  ctx.save();
  ctx.translate((1 - rightP) * 40, shiftY);
  ctx.globalAlpha = clamp(rightP) * (1 - exitP);

  drawEyebrowPill(ctx, 994, 125, 'Transactional');
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = '500 42px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Replace Resend. Same domain.', 994, 200);
  ctx.font = '400 19px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('A priority lane so a 50,000-recipient campaign never delays an OTP.', 994, 244);

  const tx = drawWashCard(ctx, 994, 280, 830, 690, 24, false);

  // Header: send.ts
  ctx.strokeStyle = COLORS.border;
  ctx.beginPath();
  ctx.moveTo(tx.ix, tx.iy + 52);
  ctx.lineTo(tx.ix + tx.iw, tx.iy + 52);
  ctx.stroke();
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
