  ctx.save();
  ctx.translate((1 - termP) * -50, shiftY);
  ctx.globalAlpha = clamp(termP) * (1 - exitP);

  const { ix, iy, iw, ih } = drawWashCard(ctx, 100, 160, 1000, 720, 26, true);

  // Terminal Header Bar
  ctx.strokeStyle = COLORS.darkBorder;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(ix, iy + 62);
  ctx.lineTo(ix + iw, iy + 62);
  ctx.stroke();

  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ix + 28 + d * 18, iy + 31, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.16)';
    ctx.fill();
