  ctx.font = '500 16px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.darkMutedFg;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('claude', ix + 92, iy + 31);

  // Right badge: [● lumail · 139 tools]
  const badgeW = 212;
  roundRect(ctx, ix + iw - badgeW - 24, iy + 14, badgeW, 34, 8);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.04)';
  ctx.fill();
  ctx.strokeStyle = COLORS.darkBorder;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(ix + iw - badgeW - 6, iy + 31, 4.5, 0, Math.PI * 2);
  ctx.fillStyle = COLORS.emerald;
  ctx.fill();

  ctx.font = '500 14px "Geist Mono", monospace';
  ctx.fillStyle = '#F7F8F8';
  ctx.fillText('lumail · 139 tools', ix + iw - badgeW + 8, iy + 31);

  // User Query 1
  const q1Y = iy + 114;
