  ctx.fillText('$0', b1X + 28, bY + 106);
  ctx.font = '400 18px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('/month', b1X + 102, bY + 114);

  const freePerks = [
    '3,000 emails/month free',
    'Unlimited subscribers',
    'Unlimited workflows',
    'MCP, API, CLI & SDK access',
    'No credit card required',
  ];
  freePerks.forEach((fp, i) => {
    ctx.font = '400 16px "Geist", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(`✓  ${fp}`, b1X + 28, bY + 175 + i * 38);
  });

  // Box 2: Creator Plan (Best Match)
  const b2X = pc.ix + 408;
  roundRect(ctx, b2X, bY, bW, bH, 18);
  ctx.fillStyle = COLORS.white;
  ctx.fill();
  ctx.strokeStyle = COLORS.flare;
  ctx.lineWidth = 2.5;
  ctx.stroke();

  // Best Match pill
  roundRect(ctx, b2X + bW - 134, bY + 22, 110, 28, 14);
  ctx.fillStyle = COLORS.peach;
  ctx.fill();
  ctx.font = '600 12px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.ember;
  ctx.textAlign = 'center';
  ctx.fillText('BEST MATCH', b2X + bW - 79, bY + 37);

  ctx.textAlign = 'left';
  ctx.font = '600 20px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Creator', b2X + 28, bY + 42);
  ctx.font = '600 54px "Inter", sans-serif';
  ctx.fillText('$20', b2X + 28, bY + 106);
  ctx.font = '400 18px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('/month · 40K emails', b2X + 132, bY + 114);

  const creatorPerks = [
    '40,000 emails/month included',
    'Unlimited contacts ($0 list fee)',
    'Bring your own Claude/ChatGPT',
    '10 sending domains + custom web',
    'Remove "Sent with Lumail" badge',
  ];
  creatorPerks.forEach((cp, i) => {
    ctx.font = '400 16px "Geist", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(`✓  ${cp}`, b2X + 28, bY + 175 + i * 38);
  });
  ctx.restore();

  // Right Card: Live Delivery Analytics & Social Proof ("3M+ emails sent")
  const rightP = springProg(lt, 0.4, 0.7, 0.74, 11);
  ctx.save();
  ctx.translate((1 - rightP) * 45, shiftY);
  ctx.globalAlpha = clamp(rightP) * (1 - exitP);

  const an = drawWashCard(ctx, 980, 290, 840, 660, 26, false);

  ctx.textAlign = 'left';
  ctx.font = '600 22px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Real-time delivery & conversion analytics', an.ix + 36, an.iy + 52);

  // 4 Metric Cards using exact Lumail CSS metric colors:
  // --metric-delivered:#5b9cf0; --metric-opened:#3fbd87; --metric-clicked:#e0a04a;
  const metrics = [
    { label: 'DELIVERED', val: '99.8%', sub: '39,920 / 40,000', color: COLORS.metricDelivered, pct: 0.998 },
    { label: 'OPEN RATE', val: '64.2%', sub: '25,628 unique opens', color: COLORS.metricOpened, pct: 0.642 },
    { label: 'CLICK RATE', val: '18.4%', sub: '7,345 link clicks', color: COLORS.metricClicked, pct: 0.48 },
    { label: 'REVENUE', val: '$14,820', sub: 'from 312 hot-lead conversions', color: COLORS.flare, pct: 0.86 },
  ];

  metrics.forEach((m, i) => {
    const mp = easeOutQuart(prog(lt, 0.9 + i * 0.22, 0.9));
    const col = i % 2;
    const row = Math.floor(i / 2);
    const mx = an.ix + 36 + col * 366;
    const my = an.iy + 94 + row * 158;

    roundRect(ctx, mx, my, 344, 138, 16);
    ctx.fillStyle = COLORS.muted;
    ctx.fill();

    ctx.textAlign = 'left';
    ctx.font = '600 13px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(m.label, mx + 22, my + 30);

    ctx.font = '600 38px "Inter", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(m.val, mx + 22, my + 72);

    ctx.font = '400 14px "Geist", sans-serif';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(m.sub, mx + 22, my + 104);

    // Animated metric bar
    roundRect(ctx, mx + 22, my + 118, 300, 6, 3);
    ctx.fillStyle = 'rgba(26, 22, 20, 0.08)';
    ctx.fill();
    roundRect(ctx, mx + 22, my + 118, 300 * m.pct * mp, 6, 3);
    ctx.fillStyle = m.color;
    ctx.fill();
  });

  // Founder & Customer Quote Card at bottom of Right Card
  const qY = an.iy + 426;
  roundRect(ctx, an.ix + 36, qY, an.iw - 72, 148, 18);
  ctx.fillStyle = COLORS.wash;
  ctx.fill();
  ctx.strokeStyle = COLORS.peach;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.textAlign = 'left';
  ctx.font = '400 19px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText(
    '“Now my agent reviews it, fixes it, and sends it for me.',
    an.ix + 62,
    qY + 46
  );
  ctx.fillText(
    'I’ve sent over 3 million emails with Lumail.”',
    an.ix + 62,
    qY + 76
  );

  ctx.font = '600 15px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.ember;
  ctx.fillText('MELVYN · FOUNDER, LUMAIL.IO · 3M+ EMAILS SENT', an.ix + 62, qY + 116);

  ctx.restore();
  ctx.restore();
}

// ============================================================================
// SCENE 8 (40.0s - 45.0s): THE GRAND FINALE LOCKUP — LUMAIL.IO
// ============================================================================
export function renderScene8(ctx, t) {
  const lt = t - 40.0; // 0.0 -> 5.0s
  drawPaperBackground(ctx, t, 0.5, 0.42);

  // Subtle expanding warm rings behind the lockup
  const ringP = easeOutQuart(prog(lt, 0.0, 2.2));
  ctx.save();
  ctx.beginPath();
  ctx.arc(W / 2, 340, 220 + ringP * 420, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(255, 51, 0, 0.07)';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W / 2, 340, 120 + ringP * 260, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(255, 51, 0, 0.11)';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.restore();

  // Official Lumail Lockup (strictly following brand guidelines: quarter-mark clear space, exact proportions)
  const logoP = springProg(lt, 0.1, 0.85, 0.72, 10);
  const lockH = 132;
  const lockW = (311.71 / 91) * lockH;

  ctx.save();
  const logoY = 215 + (1 - logoP) * 35;
  ctx.globalAlpha = clamp(logoP);
  drawLumailLockup(ctx, (W - lockW) / 2, logoY, lockH, false);
  ctx.restore();

  // Direct, Precise, Calm Headline ("Import your list. Send tonight.")
  const hP = springProg(lt, 0.45, 0.75, 0.74, 11);
  ctx.save();
  ctx.globalAlpha = clamp(hP);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = '500 68px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Import your list. Send tonight.', W / 2, 445 + (1 - hP) * 28);

  ctx.font = '400 26px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText(
    'Email for people who write, ship and sell. Campaigns, sequences and transactional, one domain.',
    W / 2,
    520 + (1 - hP) * 28
  );
  ctx.restore();

  // The Single Filled Flare CTA Pill ("Start free at lumail.io →")
  const ctaP = springProg(lt, 0.85, 0.75, 0.7, 11);
  if (ctaP > 0) {
    ctx.save();
    const btnW = 460;
    const btnH = 84;
    const btnX = (W - btnW) / 2;
    const btnY = 600 + (1 - ctaP) * 30;

    ctx.globalAlpha = clamp(ctaP);
    ctx.shadowColor = 'rgba(255, 51, 0, 0.30)';
    ctx.shadowBlur = 36;
    ctx.shadowOffsetY = 14;
    roundRect(ctx, btnX, btnY, btnW, btnH, 42);
    ctx.fillStyle = COLORS.flare;
    ctx.fill();
    ctx.shadowColor = 'transparent';

    ctx.font = '500 28px "Geist", sans-serif';
    ctx.fillStyle = COLORS.white;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Start free at lumail.io', W / 2 - 18, btnY + btnH / 2 + 1);
    drawSvgIcon(ctx, ARROW_RIGHT_PATH_STR, W / 2 + 148, btnY + btnH / 2 - 14, 28, COLORS.white);
    ctx.restore();
  }

  // Bottom 4 Summary Badges
  const badges = [
    '3,000 emails/month free · no card',
    'Pay for emails sent, never subscribers',
    '139 MCP tools for Claude, Codex & ChatGPT',
    'Newsletters · Workflows · Transactional',
  ];

  const bp = easeProg(lt, 1.25, 0.7);
  if (bp > 0) {
    ctx.save();
    ctx.globalAlpha = bp;
    const rowY = 775;
    const positions = [265, 730, 1215, 1675];
    badges.forEach((b, i) => {
      const x = positions[i];
      ctx.font = '500 15px "Geist Mono", monospace';
      ctx.fillStyle = COLORS.ink;
      ctx.textAlign = 'center';
      ctx.fillText(b, x, rowY);

      if (i < 3) {
        ctx.beginPath();
        ctx.arc((positions[i] + positions[i + 1]) / 2, rowY - 4, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.flare;
        ctx.fill();
      }
    });

    // Bottom URL watermark
    ctx.font = '500 17px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.textAlign = 'center';
    ctx.fillText('https://lumail.io', W / 2, 965);
    ctx.restore();
  }
}

