import {
  W, H, COLORS, clamp, lerp, easeOutCubic, easeOutQuart, easeOutQuint,
  easeInOutCubic, spring, prog, easeProg, springProg,
  SPARKLE_PATH_STR, ENVELOPE_PATH_STR, CHECK_PATH_STR, ARROW_RIGHT_PATH_STR,
  roundRect, drawLumailMark, drawLumailLockup, drawSvgIcon,
  drawEyebrowPill, drawWashCard, drawPaperBackground, drawTopChrome
} from '/tmp/scenes_helpers.mjs';

// ============================================================================
// SCENE 5 (22.0s - 28.5s): YOUR AI CAN SEND THE CAMPAIGN — 139 MCP TOOLS (DARK VOID)
// ============================================================================
export function renderScene5(ctx, t) {
  const lt = t - 22.0; // 0.0 -> 6.5s
  const exitP = easeInOutCubic(prog(lt, 6.05, 0.45));

  // Void Dark Canvas (#08090A) with subtle Flare/Ember ambient glow
  ctx.fillStyle = COLORS.void;
  ctx.fillRect(0, 0, W, H);

  const grad = ctx.createRadialGradient(W * 0.35, H * 0.5, 40, W * 0.35, H * 0.5, 920);
  grad.addColorStop(0, 'rgba(255, 51, 0, 0.14)');
  grad.addColorStop(0.55, 'rgba(196, 50, 10, 0.05)');
  grad.addColorStop(1, 'rgba(8, 9, 10, 0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // Subtle dark grid
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  ctx.lineWidth = 1;
  const grid = 80;
  const offset = (t * 16) % grid;
  ctx.beginPath();
  for (let x = offset; x < W; x += grid) {
    ctx.moveTo(x, 0);
    ctx.lineTo(x, H);
  }
  for (let y = 0; y < H; y += grid) {
    ctx.moveTo(0, y);
    ctx.lineTo(W, y);
  }
  ctx.stroke();

  drawTopChrome(ctx, 'AGENT ACCESS · 139 MCP TOOLS', '04', true, 1 - exitP);

  ctx.save();
  ctx.globalAlpha = 1 - exitP;
  const shiftY = -exitP * 45;

  // Left Column: Claude MCP Terminal Window (exact match to lumail.io #agents)
  const termP = springProg(lt, 0.08, 0.72, 0.74, 11);
  ctx.save();
  ctx.translate((1 - termP) * -50, shiftY);
  ctx.globalAlpha = clamp(termP) * (1 - exitP);

  const { ix, iy, iw, ih } = drawWashCard(ctx, 100, 160, 1000, 720, 26, true);

  // Terminal Header Bar
  ctx.strokeStyle = COLORS.darkBorder;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(ix, iy + 62);
  ctx.lineTo(ix + iw, iy + 62);
  ctx.stroke();

  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(ix + 28 + d * 18, iy + 31, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.16)';
    ctx.fill();
  }

  ctx.font = '500 16px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.darkMutedFg;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText('claude', ix + 92, iy + 31);

  // Right badge: [● lumail · 139 tools]
  const badgeW = 212;
  roundRect(ctx, ix + iw - badgeW - 24, iy + 14, badgeW, 34, 8);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.04)';
  ctx.fill();
  ctx.strokeStyle = COLORS.darkBorder;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(ix + iw - badgeW - 6, iy + 31, 4.5, 0, Math.PI * 2);
  ctx.fillStyle = COLORS.emerald;
  ctx.fill();

  ctx.font = '500 14px "Geist Mono", monospace';
  ctx.fillStyle = '#F7F8F8';
  ctx.fillText('lumail · 139 tools', ix + iw - badgeW + 8, iy + 31);

  // User Query 1
  const q1Y = iy + 114;
  ctx.font = '400 19px "Geist Mono", monospace';
  ctx.fillStyle = 'rgba(255, 255, 255, 0.35)';
  ctx.fillText('>', ix + 36, q1Y);
  ctx.fillStyle = '#D1D5DB';
  ctx.fillText('who clicked the pricing link but never bought?', ix + 64, q1Y);

  // 3 Live MCP Tool Executions
  const agentSteps = [
    {
      fn: 'lumail - query_subscribers',
      arg: '(clicked: "/pricing")',
      res: '312 subscribers',
      start: 0.95,
    },
    {
      fn: 'lumail - bulk_add_tags',
      arg: '(tags: ["hot-lead"])',
      res: '312 tagged',
      start: 1.95,
    },
    {
      fn: 'lumail - add_subscriber_to_workflow',
      arg: '(workflow: "Objections")',
      res: '312 enrolled',
      start: 2.95,
    },
  ];

  agentSteps.forEach((st, idx) => {
    const sp = easeProg(lt, st.start, 0.55);
    if (sp <= 0) return;
    const sy = iy + 182 + idx * 108;

    ctx.save();
    ctx.globalAlpha = sp * (1 - exitP);
    ctx.translate(0, (1 - sp) * 16);

    ctx.beginPath();
    ctx.arc(ix + 44, sy, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.emerald;
    ctx.fill();

    ctx.font = '500 18px "Geist Mono", monospace';
    ctx.fillStyle = '#F7F8F8';
    ctx.fillText(st.fn, ix + 64, sy);
    const w1 = ctx.measureText(st.fn + ' ').width;

    ctx.fillStyle = COLORS.darkMutedFg;
    ctx.fillText('(MCP) ', ix + 64 + w1, sy);
    const w2 = ctx.measureText('(MCP) ').width;

    ctx.fillStyle = COLORS.coral;
    ctx.fillText(st.arg, ix + 64 + w1 + w2, sy);

    // Output line
    ctx.font = '400 18px "Geist Mono", monospace';
    ctx.fillStyle = '#A1A1AA';
    ctx.fillText(`⎿  ${st.res}`, ix + 68, sy + 34);
    ctx.restore();
  });

  // Done confirmation line
  const doneP = easeProg(lt, 3.85, 0.5);
  if (doneP > 0) {
    const dy = iy + 512;
    ctx.save();
    ctx.globalAlpha = doneP * (1 - exitP);
    ctx.beginPath();
    ctx.arc(ix + 44, dy, 5.5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.emerald;
    ctx.fill();

    ctx.font = '500 19px "Geist Mono", monospace';
    ctx.fillStyle = '#F7F8F8';
    ctx.fillText('Done. The first email goes out in 2 hours.', ix + 64, dy);
    ctx.restore();
  }

  // Follow-up input box at bottom of terminal: "> show me the numbers on Thursday"
  const nextP = easeProg(lt, 4.35, 0.55);
  if (nextP > 0) {
    const bx = ix + 34;
    const by = iy + 562;
    const bw = iw - 68;
    ctx.save();
    ctx.globalAlpha = nextP * (1 - exitP);
    roundRect(ctx, bx, by, bw, 62, 14);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.fill();
    ctx.strokeStyle = COLORS.darkBorder;
    ctx.stroke();

    const promptStr = 'show me the numbers on Thursday';
    const typeP = prog(lt, 4.5, 0.95);
    const shown = promptStr.slice(0, Math.floor(typeP * promptStr.length));

    ctx.font = '400 18px "Geist Mono", monospace';
    ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
    ctx.fillText('>', bx + 22, by + 31);
    ctx.fillStyle = '#F7F8F8';
    ctx.fillText(shown, bx + 48, by + 31);

    const curW = ctx.measureText(shown).width;
    if (Math.floor(lt * 4) % 2 === 0) {
      ctx.fillStyle = COLORS.flare;
      ctx.fillRect(bx + 52 + curW, by + 18, 9, 24);
    }
    ctx.restore();
  }
  ctx.restore();

  // Right Column: Headline, Copy, and Agent Ecosystem Grid
  const rightP = springProg(lt, 0.25, 0.75, 0.74, 11);
  ctx.save();
  ctx.translate((1 - rightP) * 45, shiftY);
  ctx.globalAlpha = clamp(rightP) * (1 - exitP);

  drawEyebrowPill(ctx, 1160, 175, 'AI · MODEL CONTEXT PROTOCOL', true);

  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = '500 56px "Inter", sans-serif';
  ctx.fillStyle = '#F7F8F8';
  ctx.fillText('Your AI can send', 1160, 270);
  ctx.fillStyle = COLORS.flare;
  ctx.fillText('the campaign.', 1160, 340);

  ctx.font = '400 22px "Geist", sans-serif';
  ctx.fillStyle = COLORS.darkMutedFg;
  ctx.fillText('Connect the agent you already use. It drafts,', 1160, 418);
  ctx.fillText('segments, and schedules. You keep the last click.', 1160, 452);
  ctx.fillText('No dashboard tour required.', 1160, 486);

  // Connected Agent Cards Grid (Claude Code, Codex, ChatGPT, Lumail CLI)
  const agents = [
    { name: 'Claude Code', sub: 'lumail.io/claude-code/install', tag: 'PLUGIN + MCP' },
    { name: 'OpenAI Codex', sub: 'lumail.io/codex/install', tag: 'OAUTH 2.1' },
    { name: 'ChatGPT', sub: 'https://lumail.io/mcp', tag: 'SCOPED OAUTH' },
    { name: 'Lumail CLI + SDK', sub: 'lumail campaigns send', tag: 'TERMINAL + TS' },
  ];

  agents.forEach((ag, i) => {
    const ap = springProg(lt, 0.8 + i * 0.22, 0.6, 0.74, 11);
    if (ap <= 0) return;
    const ay = 540 + i * 82;
    ctx.save();
    ctx.globalAlpha = ap * (1 - exitP);
    roundRect(ctx, 1160, ay, 660, 68, 16);
    ctx.fillStyle = COLORS.darkCard;
    ctx.fill();
    ctx.strokeStyle = COLORS.darkBorder;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Dark Lumail mark on left or status dot
    ctx.beginPath();
    ctx.arc(1192, ay + 34, 5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.flare;
    ctx.fill();

    ctx.font = '600 19px "Geist", sans-serif';
    ctx.fillStyle = '#F7F8F8';
    ctx.textAlign = 'left';
    ctx.fillText(ag.name, 1214, ay + 25);

    ctx.font = '400 14px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.darkMutedFg;
    ctx.fillText(ag.sub, 1214, ay + 47);

    // Right Tag
    ctx.font = '500 12px "Geist Mono", monospace';
    const tw = ctx.measureText(ag.tag).width + 24;
    roundRect(ctx, 1160 + 660 - tw - 20, ay + 19, tw, 30, 8);
    ctx.fillStyle = 'rgba(255, 255, 255, 0.06)';
    ctx.fill();
    ctx.fillStyle = '#E5E7EB';
    ctx.textAlign = 'center';
    ctx.fillText(ag.tag, 1160 + 660 - tw / 2 - 20, ay + 35);

    ctx.restore();
  });

  ctx.restore();
  ctx.restore();
}

// ============================================================================
// SCENE 6 (28.5s - 34.5s): WORKFLOWS THAT KEEP RUNNING + TRANSACTIONAL PRIORITY LANE
// ============================================================================
export function renderScene6(ctx, t) {
  const lt = t - 28.5; // 0.0 -> 6.0s
  drawPaperBackground(ctx, t, 0.5, 0.5);
  const exitP = easeInOutCubic(prog(lt, 5.55, 0.45));
  drawTopChrome(ctx, 'WORKFLOWS & TRANSACTIONAL', '05', false, 1 - exitP);

  ctx.save();
  ctx.globalAlpha = 1 - exitP;
  const shiftY = -exitP * 40;

  // Left Half: Visual Workflow Graph ("Welcome sequence" from lumail.io)
  const leftP = springProg(lt, 0.05, 0.7, 0.74, 11);
  ctx.save();
  ctx.translate((1 - leftP) * -40, shiftY);
  ctx.globalAlpha = clamp(leftP) * (1 - exitP);

  drawEyebrowPill(ctx, 96, 125, 'Workflows');
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = '500 42px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Sequences that keep running.', 96, 200);
  ctx.font = '400 19px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('Welcome, launch, follow-up. Publish once. Lumail handles enrolment & exits.', 96, 244);

  const wf = drawWashCard(ctx, 96, 280, 830, 690, 24, false);

  // Window header
  ctx.strokeStyle = COLORS.border;
  ctx.beginPath();
  ctx.moveTo(wf.ix, wf.iy + 52);
  ctx.lineTo(wf.ix + wf.iw, wf.iy + 52);
  ctx.stroke();
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(wf.ix + 24 + d * 16, wf.iy + 26, 5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(26, 22, 20, 0.14)';
    ctx.fill();
  }
  ctx.font = '500 15px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('Welcome sequence · Published v3', wf.ix + 82, wf.iy + 26);

  // Graph Nodes
  const cx = wf.ix + wf.iw / 2;
  const nodes = [
    { y: wf.iy + 104, label: 'Tag added', val: 'newsletter', tag: 'TRIGGER', delay: 0.35 },
    { y: wf.iy + 224, label: 'Send email', val: 'Welcome, start here', tag: 'ACTION', delay: 0.85 },
    { y: wf.iy + 344, label: 'Wait', val: '2 days', tag: 'DELAY', delay: 1.35 },
    { y: wf.iy + 464, label: 'If opened', val: 'the welcome email', tag: 'CONDITION', delay: 1.85 },
  ];

  // Draw connecting edges + animated pulse dots
  nodes.forEach((n, idx) => {
    const np = springProg(lt, n.delay, 0.55, 0.72, 12);
    if (np <= 0) return;

    if (idx > 0) {
      const prevY = nodes[idx - 1].y + 36;
      const curY = n.y - 36;
      ctx.strokeStyle = COLORS.border;
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(cx, prevY);
      ctx.lineTo(cx, curY);
      ctx.stroke();

      // Animated data pulse along edge
      const pulseU = (lt * 1.4 - idx * 0.3) % 1;
      if (pulseU > 0 && pulseU < 1) {
        ctx.beginPath();
        ctx.arc(cx, lerp(prevY, curY, pulseU), 4.5, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.flare;
        ctx.fill();
      }
    }

    ctx.save();
    ctx.translate(cx, n.y);
    ctx.scale(lerp(0.85, 1, np), lerp(0.85, 1, np));
    ctx.translate(-cx, -n.y);
    ctx.globalAlpha = np * (1 - exitP);

    const nw = 440;
    const nh = 72;
    roundRect(ctx, cx - nw / 2, n.y - nh / 2, nw, nh, 14);
    ctx.fillStyle = COLORS.white;
    ctx.fill();
    ctx.strokeStyle = idx === 3 ? COLORS.coral : COLORS.border;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // Left icon square
    roundRect(ctx, cx - nw / 2 + 16, n.y - 22, 44, 44, 10);
    ctx.fillStyle = COLORS.peach;
    ctx.fill();
    ctx.beginPath();
    ctx.arc(cx - nw / 2 + 38, n.y, 5, 0, Math.PI * 2);
    ctx.fillStyle = COLORS.ember;
    ctx.fill();

    ctx.textAlign = 'left';
    ctx.font = '500 18px "Geist", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(n.label, cx - nw / 2 + 76, n.y - 10);

    ctx.font = '400 15px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(n.val, cx - nw / 2 + 76, n.y + 14);

    // Right badge
    ctx.font = '500 11px "Geist Mono", monospace';
    const tw = ctx.measureText(n.tag).width + 18;
    roundRect(ctx, cx + nw / 2 - tw - 16, n.y - 12, tw, 24, 6);
    ctx.fillStyle = COLORS.muted;
    ctx.fill();
    ctx.fillStyle = COLORS.mutedFg;
    ctx.textAlign = 'center';
    ctx.fillText(n.tag, cx + nw / 2 - tw / 2 - 16, n.y + 1);
    ctx.restore();
  });

  // Branching Yes / No outcomes below "If opened"
  const branchP = springProg(lt, 2.35, 0.55, 0.72, 12);
  if (branchP > 0) {
    ctx.save();
    ctx.globalAlpha = branchP * (1 - exitP);
    const startY = nodes[3].y + 36;
    const branchY = wf.iy + 585;

    ctx.strokeStyle = COLORS.border;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx, startY);
    ctx.lineTo(cx - 145, branchY - 28);
    ctx.moveTo(cx, startY);
    ctx.lineTo(cx + 145, branchY - 28);
    ctx.stroke();

    // Yes node
    roundRect(ctx, cx - 265, branchY - 28, 230, 56, 12);
    ctx.fillStyle = '#ECFDF5';
    ctx.fill();
    ctx.strokeStyle = 'rgba(5, 150, 105, 0.3)';
    ctx.stroke();
    ctx.font = '600 15px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.emeraldDark;
    ctx.textAlign = 'center';
    ctx.fillText('YES · Send pitch offer', cx - 150, branchY + 1);

    // No node
    roundRect(ctx, cx + 35, branchY - 28, 230, 56, 12);
    ctx.fillStyle = COLORS.muted;
    ctx.fill();
    ctx.strokeStyle = COLORS.border;
    ctx.stroke();
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText('NO · Re-send with new subject', cx + 150, branchY + 1);
    ctx.restore();
  }
  ctx.restore();

  // Right Half: Transactional Email — "Replace Resend. Same domain." + Priority Lane
  const rightP = springProg(lt, 0.25, 0.75, 0.74, 11);
  ctx.save();
  ctx.translate((1 - rightP) * 40, shiftY);
  ctx.globalAlpha = clamp(rightP) * (1 - exitP);

  drawEyebrowPill(ctx, 994, 125, 'Transactional');
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = '500 42px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Replace Resend. Same domain.', 994, 200);
  ctx.font = '400 19px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('A priority lane so a 50,000-recipient campaign never delays an OTP.', 994, 244);

  const tx = drawWashCard(ctx, 994, 280, 830, 690, 24, false);

  // Header: send.ts
  ctx.strokeStyle = COLORS.border;
  ctx.beginPath();
  ctx.moveTo(tx.ix, tx.iy + 52);
  ctx.lineTo(tx.ix + tx.iw, tx.iy + 52);
  ctx.stroke();
  for (let d = 0; d < 3; d++) {
    ctx.beginPath();
    ctx.arc(tx.ix + 24 + d * 16, tx.iy + 26, 5, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(26, 22, 20, 0.14)';
    ctx.fill();
  }
  ctx.font = '500 15px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('send.ts · TypeScript SDK', tx.ix + 82, tx.iy + 26);

  // Code block (exact match to lumail.io homepage send.ts)
  const codeLines = [
    [
      { text: 'import ', color: '#A626A4' },
      { text: '{ Lumail } ', color: COLORS.ink },
      { text: 'from ', color: '#A626A4' },
      { text: '"lumail"', color: '#50A14F' },
      { text: ';', color: COLORS.mutedFg },
    ],
    [],
    [
      { text: 'await ', color: '#A626A4' },
      { text: 'lumail.emails.', color: COLORS.ink },
      { text: 'send', color: '#4078F2' },
      { text: '({', color: COLORS.ink },
    ],
    [
      { text: '  to: ', color: '#986801' },
      { text: '"alex@startup.io"', color: '#50A14F' },
      { text: ',', color: COLORS.mutedFg },
    ],
    [
      { text: '  from: ', color: '#986801' },
      { text: '"auth@yourdomain.com"', color: '#50A14F' },
      { text: ',', color: COLORS.mutedFg },
    ],
    [
      { text: '  subject: ', color: '#986801' },
      { text: '"Your login code"', color: '#50A14F' },
      { text: ',', color: COLORS.mutedFg },
    ],
    [
      { text: '  content: ', color: '#986801' },
      { text: '"# Your code\\n\\n{{code}}"', color: '#50A14F' },
    ],
    [{ text: '});', color: COLORS.ink }],
  ];

  roundRect(ctx, tx.ix + 28, tx.iy + 76, tx.iw - 56, 305, 16);
  ctx.fillStyle = '#FAFAFA';
  ctx.fill();
  ctx.strokeStyle = COLORS.border;
  ctx.stroke();

  codeLines.forEach((tokens, lineIdx) => {
    let lx = tx.ix + 54;
    const ly = tx.iy + 112 + lineIdx * 32;
    ctx.font = '500 18px "Geist Mono", monospace';
    tokens.forEach((tk) => {
      ctx.fillStyle = tk.color;
      ctx.fillText(tk.text, lx, ly);
      lx += ctx.measureText(tk.text).width;
    });
  });

  // Status badge inside code card: [● queued · priority lane]
  roundRect(ctx, tx.ix + tx.iw - 275, tx.iy + 94, 228, 34, 17);
  ctx.fillStyle = '#ECFDF5';
  ctx.fill();
  ctx.font = '600 13px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.emeraldDark;
  ctx.textAlign = 'center';
  ctx.fillText('● queued · priority lane', tx.ix + tx.iw - 161, tx.iy + 112);

  // Dual-Lane Highway Visualization (Broadcast Lane vs Instant OTP Priority Lane)
  const laneBoxY = tx.iy + 410;
  ctx.textAlign = 'left';
  ctx.font = '600 16px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('DUAL-LANE DELIVERY ENGINE (smtp.lumail.io:587)', tx.ix + 32, laneBoxY);

  // Lane 1: Campaign Broadcast Lane
  const l1Y = laneBoxY + 34;
  roundRect(ctx, tx.ix + 28, l1Y, tx.iw - 56, 78, 14);
  ctx.fillStyle = COLORS.muted;
  ctx.fill();
  ctx.font = '500 15px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('Broadcast Lane · 50,000 Weekly Newsletter', tx.ix + 48, l1Y + 26);

  // Steady stream of campaign packets
  for (let p = 0; p < 8; p++) {
    const px = tx.ix + 48 + ((p * 86 + lt * 95) % (tx.iw - 110));
    roundRect(ctx, px, l1Y + 44, 52, 18, 5);
    ctx.fillStyle = 'rgba(26, 22, 20, 0.22)';
    ctx.fill();
  }

  // Lane 2: Instant Transactional Priority Lane
  const l2Y = laneBoxY + 128;
  roundRect(ctx, tx.ix + 28, l2Y, tx.iw - 56, 86, 14);
  ctx.fillStyle = COLORS.peach;
  ctx.fill();
  ctx.strokeStyle = COLORS.coral;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.font = '600 16px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Priority Instant Lane · Login OTP (849-201)', tx.ix + 48, l2Y + 26);

  ctx.font = '600 14px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.ember;
  ctx.textAlign = 'right';
  ctx.fillText('DELIVERED IN 180ms · ZERO QUEUE DELAY', tx.ix + tx.iw - 48, l2Y + 26);

  // High-speed Flare OTP packet zipping across Priority Lane
  const otpP = (lt * 0.85) % 1;
  const otpX = lerp(tx.ix + 48, tx.ix + tx.iw - 190, easeOutCubic(otpP));
  roundRect(ctx, otpX, l2Y + 44, 140, 26, 13);
  ctx.fillStyle = COLORS.flare;
  ctx.fill();
  ctx.font = '600 13px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.white;
  ctx.textAlign = 'center';
  ctx.fillText('OTP · 849201 →', otpX + 70, l2Y + 58);

  ctx.restore();
  ctx.restore();
}

// ============================================================================
// SCENE 7 (34.5s - 40.0s): TRANSPARENT PRICING & REAL-TIME ANALYTICS
// ============================================================================
export function renderScene7(ctx, t) {
  const lt = t - 34.5; // 0.0 -> 5.5s
  drawPaperBackground(ctx, t, 0.5, 0.3);
  const exitP = easeInOutCubic(prog(lt, 5.05, 0.45));
  drawTopChrome(ctx, 'PRICING & ANALYTICS', '06', false, 1 - exitP);

  ctx.save();
  ctx.globalAlpha = 1 - exitP;
  const shiftY = -exitP * 40;

  // Top Center Headline (exact copy from lumail.io/pricing)
  const headP = springProg(lt, 0.05, 0.65, 0.74, 11);
  ctx.save();
  ctx.translate(0, (1 - headP) * 30 + shiftY);
  ctx.globalAlpha = clamp(headP) * (1 - exitP);

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = '500 50px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('You pay for emails sent.', W / 2, 142);
  ctx.fillStyle = COLORS.flare;
  ctx.fillText('Never for subscribers stored.', W / 2, 200);

  ctx.font = '400 22px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText(
    'Import 50,000 contacts on day one. Dormant subscribers cost you $0.',
    W / 2,
    252
  );
  ctx.restore();

  // Left Card: Interactive Volume Slider & Creator Plan Card
  const leftP = springProg(lt, 0.25, 0.7, 0.74, 11);
  ctx.save();
  ctx.translate((1 - leftP) * -45, shiftY);
  ctx.globalAlpha = clamp(leftP) * (1 - exitP);

  const pc = drawWashCard(ctx, 100, 290, 840, 660, 26, false);

  ctx.textAlign = 'left';
  ctx.font = '600 22px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Emails you send each month', pc.ix + 36, pc.iy + 52);

  // Volume Stops: 1K, 5K, 20K, 40K, 100K, 400K, 1M
  const stops = ['1K', '5K', '20K', '40K', '100K', '400K', '1M'];
  const sliderP = easeInOutCubic(prog(lt, 0.6, 1.5));
  // Animate slider from 0 (Free 3K) to index 3 (40K Creator = $20/mo)
  const activePos = lerp(0.08, 0.5, sliderP);

  const trackX = pc.ix + 42;
  const trackY = pc.iy + 115;
  const trackW = pc.iw - 84;

  roundRect(ctx, trackX, trackY - 6, trackW, 12, 6);
  ctx.fillStyle = COLORS.muted;
  ctx.fill();

  roundRect(ctx, trackX, trackY - 6, trackW * activePos, 12, 6);
  ctx.fillStyle = COLORS.flare;
  ctx.fill();

  // Slider thumb
  const thumbX = trackX + trackW * activePos;
  ctx.beginPath();
  ctx.arc(thumbX, trackY, 16, 0, Math.PI * 2);
  ctx.fillStyle = COLORS.white;
  ctx.fill();
  ctx.lineWidth = 4;
  ctx.strokeStyle = COLORS.flare;
  ctx.stroke();

  stops.forEach((st, idx) => {
    const sx = trackX + (idx / (stops.length - 1)) * trackW;
    ctx.font = idx === 3 ? '600 15px "Geist Mono", monospace' : '400 14px "Geist Mono", monospace';
    ctx.fillStyle = idx === 3 ? COLORS.ink : COLORS.mutedFg;
    ctx.textAlign = 'center';
    ctx.fillText(st, sx, trackY + 34);
  });

  // Two Plan Comparison Boxes inside Left Card: FREE ($0) and CREATOR ($20)
  // Box 1: Free Plan
  const b1X = pc.ix + 36;
  const bY = pc.iy + 190;
  const bW = 342;
  const bH = 385;

  roundRect(ctx, b1X, bY, bW, bH, 18);
  ctx.fillStyle = COLORS.muted;
  ctx.fill();
  ctx.strokeStyle = COLORS.border;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.textAlign = 'left';
  ctx.font = '600 20px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Free', b1X + 28, bY + 42);
  ctx.font = '600 54px "Inter", sans-serif';
  ctx.fillText('$0', b1X + 28, bY + 106);
  ctx.font = '400 18px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('/month', b1X + 102, bY + 114);

  const freePerks = [
    '3,000 emails/month free',
    'Unlimited subscribers',
    'Unlimited workflows',
    'MCP, API, CLI & SDK access',
    'No credit card required',
  ];
  freePerks.forEach((fp, i) => {
    ctx.font = '400 16px "Geist", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(`✓  ${fp}`, b1X + 28, bY + 175 + i * 38);
  });

  // Box 2: Creator Plan (Best Match)
  const b2X = pc.ix + 408;
  roundRect(ctx, b2X, bY, bW, bH, 18);
  ctx.fillStyle = COLORS.white;
  ctx.fill();
  ctx.strokeStyle = COLORS.flare;
  ctx.lineWidth = 2.5;
  ctx.stroke();

  // Best Match pill
  roundRect(ctx, b2X + bW - 134, bY + 22, 110, 28, 14);
  ctx.fillStyle = COLORS.peach;
  ctx.fill();
  ctx.font = '600 12px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.ember;
  ctx.textAlign = 'center';
  ctx.fillText('BEST MATCH', b2X + bW - 79, bY + 37);

  ctx.textAlign = 'left';
  ctx.font = '600 20px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Creator', b2X + 28, bY + 42);
  ctx.font = '600 54px "Inter", sans-serif';
  ctx.fillText('$20', b2X + 28, bY + 106);
  ctx.font = '400 18px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText('/month · 40K emails', b2X + 132, bY + 114);

  const creatorPerks = [
    '40,000 emails/month included',
    'Unlimited contacts ($0 list fee)',
    'Bring your own Claude/ChatGPT',
    '10 sending domains + custom web',
    'Remove "Sent with Lumail" badge',
  ];
  creatorPerks.forEach((cp, i) => {
    ctx.font = '400 16px "Geist", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(`✓  ${cp}`, b2X + 28, bY + 175 + i * 38);
  });
  ctx.restore();

  // Right Card: Live Delivery Analytics & Social Proof ("3M+ emails sent")
  const rightP = springProg(lt, 0.4, 0.7, 0.74, 11);
  ctx.save();
  ctx.translate((1 - rightP) * 45, shiftY);
  ctx.globalAlpha = clamp(rightP) * (1 - exitP);

  const an = drawWashCard(ctx, 980, 290, 840, 660, 26, false);

  ctx.textAlign = 'left';
  ctx.font = '600 22px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Real-time delivery & conversion analytics', an.ix + 36, an.iy + 52);

  // 4 Metric Cards using exact Lumail CSS metric colors:
  // --metric-delivered:#5b9cf0; --metric-opened:#3fbd87; --metric-clicked:#e0a04a;
  const metrics = [
    { label: 'DELIVERED', val: '99.8%', sub: '39,920 / 40,000', color: COLORS.metricDelivered, pct: 0.998 },
    { label: 'OPEN RATE', val: '64.2%', sub: '25,628 unique opens', color: COLORS.metricOpened, pct: 0.642 },
    { label: 'CLICK RATE', val: '18.4%', sub: '7,345 link clicks', color: COLORS.metricClicked, pct: 0.48 },
    { label: 'REVENUE', val: '$14,820', sub: 'from 312 hot-lead conversions', color: COLORS.flare, pct: 0.86 },
  ];

  metrics.forEach((m, i) => {
    const mp = easeOutQuart(prog(lt, 0.9 + i * 0.22, 0.9));
    const col = i % 2;
    const row = Math.floor(i / 2);
    const mx = an.ix + 36 + col * 366;
    const my = an.iy + 94 + row * 158;

    roundRect(ctx, mx, my, 344, 138, 16);
    ctx.fillStyle = COLORS.muted;
    ctx.fill();

    ctx.textAlign = 'left';
    ctx.font = '600 13px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(m.label, mx + 22, my + 30);

    ctx.font = '600 38px "Inter", sans-serif';
    ctx.fillStyle = COLORS.ink;
    ctx.fillText(m.val, mx + 22, my + 72);

    ctx.font = '400 14px "Geist", sans-serif';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.fillText(m.sub, mx + 22, my + 104);

    // Animated metric bar
    roundRect(ctx, mx + 22, my + 118, 300, 6, 3);
    ctx.fillStyle = 'rgba(26, 22, 20, 0.08)';
    ctx.fill();
    roundRect(ctx, mx + 22, my + 118, 300 * m.pct * mp, 6, 3);
    ctx.fillStyle = m.color;
    ctx.fill();
  });

  // Founder & Customer Quote Card at bottom of Right Card
  const qY = an.iy + 426;
  roundRect(ctx, an.ix + 36, qY, an.iw - 72, 148, 18);
  ctx.fillStyle = COLORS.wash;
  ctx.fill();
  ctx.strokeStyle = COLORS.peach;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.textAlign = 'left';
  ctx.font = '400 19px "Geist", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText(
    '“Now my agent reviews it, fixes it, and sends it for me.',
    an.ix + 62,
    qY + 46
  );
  ctx.fillText(
    'I’ve sent over 3 million emails with Lumail.”',
    an.ix + 62,
    qY + 76
  );

  ctx.font = '600 15px "Geist Mono", monospace';
  ctx.fillStyle = COLORS.ember;
  ctx.fillText('MELVYN · FOUNDER, LUMAIL.IO · 3M+ EMAILS SENT', an.ix + 62, qY + 116);

  ctx.restore();
  ctx.restore();
}

// ============================================================================
// SCENE 8 (40.0s - 45.0s): THE GRAND FINALE LOCKUP — LUMAIL.IO
// ============================================================================
export function renderScene8(ctx, t) {
  const lt = t - 40.0; // 0.0 -> 5.0s
  drawPaperBackground(ctx, t, 0.5, 0.42);

  // Subtle expanding warm rings behind the lockup
  const ringP = easeOutQuart(prog(lt, 0.0, 2.2));
  ctx.save();
  ctx.beginPath();
  ctx.arc(W / 2, 340, 220 + ringP * 420, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(255, 51, 0, 0.07)';
  ctx.lineWidth = 2;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W / 2, 340, 120 + ringP * 260, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(255, 51, 0, 0.11)';
  ctx.lineWidth = 1.5;
  ctx.stroke();
  ctx.restore();

  // Official Lumail Lockup (strictly following brand guidelines: quarter-mark clear space, exact proportions)
  const logoP = springProg(lt, 0.1, 0.85, 0.72, 10);
  const lockH = 132;
  const lockW = (311.71 / 91) * lockH;

  ctx.save();
  const logoY = 215 + (1 - logoP) * 35;
  ctx.globalAlpha = clamp(logoP);
  drawLumailLockup(ctx, (W - lockW) / 2, logoY, lockH, false);
  ctx.restore();

  // Direct, Precise, Calm Headline ("Import your list. Send tonight.")
  const hP = springProg(lt, 0.45, 0.75, 0.74, 11);
  ctx.save();
  ctx.globalAlpha = clamp(hP);
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = '500 68px "Inter", sans-serif';
  ctx.fillStyle = COLORS.ink;
  ctx.fillText('Import your list. Send tonight.', W / 2, 445 + (1 - hP) * 28);

  ctx.font = '400 26px "Geist", sans-serif';
  ctx.fillStyle = COLORS.mutedFg;
  ctx.fillText(
    'Email for people who write, ship and sell. Campaigns, sequences and transactional, one domain.',
    W / 2,
    520 + (1 - hP) * 28
  );
  ctx.restore();

  // The Single Filled Flare CTA Pill ("Start free at lumail.io →")
  const ctaP = springProg(lt, 0.85, 0.75, 0.7, 11);
  if (ctaP > 0) {
    ctx.save();
    const btnW = 460;
    const btnH = 84;
    const btnX = (W - btnW) / 2;
    const btnY = 600 + (1 - ctaP) * 30;

    ctx.globalAlpha = clamp(ctaP);
    ctx.shadowColor = 'rgba(255, 51, 0, 0.30)';
    ctx.shadowBlur = 36;
    ctx.shadowOffsetY = 14;
    roundRect(ctx, btnX, btnY, btnW, btnH, 42);
    ctx.fillStyle = COLORS.flare;
    ctx.fill();
    ctx.shadowColor = 'transparent';

    ctx.font = '500 28px "Geist", sans-serif';
    ctx.fillStyle = COLORS.white;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Start free at lumail.io', W / 2 - 18, btnY + btnH / 2 + 1);
    drawSvgIcon(ctx, ARROW_RIGHT_PATH_STR, W / 2 + 148, btnY + btnH / 2 - 14, 28, COLORS.white);
    ctx.restore();
  }

  // Bottom 4 Summary Badges
  const badges = [
    '3,000 emails/month free · no card',
    'Pay for emails sent, never subscribers',
    '139 MCP tools for Claude, Codex & ChatGPT',
    'Newsletters · Workflows · Transactional',
  ];

  const bp = easeProg(lt, 1.25, 0.7);
  if (bp > 0) {
    ctx.save();
    ctx.globalAlpha = bp;
    const rowY = 775;
    const positions = [265, 730, 1215, 1675];
    badges.forEach((b, i) => {
      const x = positions[i];
      ctx.font = '500 15px "Geist Mono", monospace';
      ctx.fillStyle = COLORS.ink;
      ctx.textAlign = 'center';
      ctx.fillText(b, x, rowY);

      if (i < 3) {
        ctx.beginPath();
        ctx.arc((positions[i] + positions[i + 1]) / 2, rowY - 4, 3.5, 0, Math.PI * 2);
        ctx.fillStyle = COLORS.flare;
        ctx.fill();
      }
    });

    // Bottom URL watermark
    ctx.font = '500 17px "Geist Mono", monospace';
    ctx.fillStyle = COLORS.mutedFg;
    ctx.textAlign = 'center';
    ctx.fillText('https://lumail.io', W / 2, 965);
    ctx.restore();
  }
}

