ffprobe -v error -show_format -show_streams video.mp4 && ls -lh video.mp4 index.html && ffmpeg -y -ss 38.0 -i video.mp4 -frames:v 1 /tmp/verify_38s.png -loglevel error && node -e '
import { chromium } from "./node_modules/playwright-core/index.mjs";
const browser = await chromium.launch({
  executablePath: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome",
  headless: true
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto("file://" + process.cwd() + "/index.html", { waitUntil: "networkidle" });
const info = await page.evaluate(async () => {
  const v = document.querySelector("video");
  if (v.readyState < 1) {
    await new Promise((r) => v.addEventListener("loadedmetadata", r, { once: true }));
  }
  v.muted = true;
  await v.play();
  await new Promise((r) => setTimeout(r, 350));
  const rect = v.getBoundingClientRect();
  return {
    title: document.title,
    headingsCount: document.querySelectorAll("h1,h2,h3,h4,h5,h6,header").length,
    controls: v.controls,
    videoWidth: v.videoWidth,
    videoHeight: v.videoHeight,
    duration: v.duration,
    currentTime: v.currentTime,
    paused: v.paused,
    rect: { width: Math.round(rect.width), height: Math.round(rect.height), left: Math.round(rect.left), top: Math.round(rect.top) },
    viewport: { width: window.innerWidth, height: window.innerHeight }
  };
});
console.log("HTML Player Verification:", JSON.stringify(info, null, 2));
await browser.close();
'

